T.split('\n').filter(Boolean).forEach((l,i)=>{const a=l.split('|');if(have.has(a[1]))return;jg.items.push({k:'jg3:'+i,cat:a[0],q:a[1],c:a.slice(2,6),e:a[6]})});
const order=[];jg.items.forEach(i=>{if(order.indexOf(i.cat)<0)order.push(i.cat)});jg.items.sort((a,b)=>order.indexOf(a.cat)-order.indexOf(b.cat));
