/* data-qa.js */
// 品質点検：複数のコースに同じ問題文があるものは、先のコース（入試文法など）に1つだけ残す
(function(){const D=window.EIGO_DATA;const seen=new Set();
for(const d of D.decks){if(d.type!=='mc'||d.listen)continue;d.items=d.items.filter(i=>{if(!i.q)return true;const k=String(i.q).trim().toLowerCase();if(seen.has(k))return false;seen.add(k);return true})}
})();

;
/* data-wrei.js */
// 英作文 例文暗記（和→英）― 英作文の講義（各課）の例文から自動で作る
(function(){
const D=window.EIGO_DATA;const es=D.decks.find(d=>d.id==='eisaku');if(!es)return;
const clean=s=>String(s).replace(/\*\*|\[\[|\]\]|[{}]/g,'').trim();
const items=[];
es.items.forEach((l,li)=>{l.body.split('\n').forEach(line=>{const m=line.match(/^([=-]) ([^|]+)\|([^|]+)\|(.+)$/);if(!m)return;
  items.push({k:'wr:'+l.k+':'+m[2].trim(),w:clean(m[3]),m:clean(m[4]),pos:l.no,li,main:m[1]==='=',sent:true})})});
D.decks.push({id:'wrei',type:'vocab',title:'英作文 例文暗記',sub:'講義の例文を日本語から英語で言えるように',items,stage:30});
const ks=D.decks.find(d=>d.id==='kaishaku');
if(ks){const it2=[];ks.items.forEach((l,li)=>{l.body.split('\n').forEach(line=>{const m=line.match(/^([=-]) ([^|]+)\|([^|]+)\|(.+)$/);if(!m)return;
  it2.push({k:'kr:'+l.k+':'+m[2].trim(),w:clean(m[3]),m:clean(m[4]),pos:l.no,li,main:m[1]==='=',sent:true})})});
  D.decks.push({id:'krei',type:'vocab',title:'英文解釈 構文の例文',sub:'講義の例文を英語から正確に訳せるように',items:it2,stage:30})}
})();

;
/* data-listen.js */
// リスニング ― 既存の単語・会話・例文から、端末の読み上げ音声を使う問題を作る
(function(){
const D=window.EIGO_DATA,by={};D.decks.forEach(d=>by[d.id]=d);
const strip=s=>String(s||'').replace(/\[|\]/g,'').replace(/\s*[~〜]\s*/g,' … ').replace(/\s+/g,' ').trim();
const bi=s=>{const o=new Set();const t=String(s).replace(/[（(].*?[)）]|[〜~、。・；;，,\s]/g,'');for(let i=0;i<t.length-1;i++)o.add(t.slice(i,i+2));return o};
const near=(a,b)=>{const A=bi(a);for(const x of bi(b))if(A.has(x))return true;return false};
const GEN=new Set("I agree.|I totally agree.|I couldn't agree more.|Sure.|Sure thing.|Anytime.|Here you are.|I see.|I'm in.|I'm game.|That's too bad.|It was okay.|You can say that again.|Piece of cake.|Why not?|I'm not sure. Let me check and get back to you.|I'm afraid I don't have the data at hand.|That sounds reasonable.|I'll pass, thanks.|That's OK.|No problem.|Of course.|Absolutely.|Exactly.|Me too.|Same here.|Good to know.|That makes sense.|I guess so.|Maybe.|I hope so.|I hope not.|Not really.|Sort of.|It depends.|Got it.|Sounds good.|No worries.|That's a good point.|I agree with you on that.|Fair enough.|Tell me about it.|You're telling me!|I know what you mean.|I'll think about it.|I have no idea.|Beats me.|Is that so?|Oh, I didn't know that.|That's great!|Really? That's great!|Go ahead.|Be my guest.|Not at all.|You're welcome.|Don't mention it.|My pleasure.|I'd love to.|Count me in!|I'm afraid I can't.|I'd rather not.|Pretty good.|Pretty good, thanks.|Not bad. And you?|Nothing much. Same as usual.|Same old, same old.|Nothing special.|I'm not so sure about that.|I agree with you to some extent, but...|That's an important point. We plan a larger study.|Yes, I learned a lot.|Seriously?|No way!|I'm glad to hear that.|Then what?|And?|So what?|Right now?|I'll take care of it.|I'm on it.".split('|'));
const others=(arr,i,get,n,ok)=>{const out=[],seen=new Set([get(arr[i])]);for(let j=1;out.length<n&&j<arr.length*3;j++){const x=arr[(i+j*37+j*j*11)%arr.length],v=get(x);if(!v||seen.has(v)||(ok&&!ok(x)))continue;seen.add(v);out.push(v)}return out};
// 1) 単語の聞き取り（Lv1〜Lv3）
const lw=[];
['lv1','lv2','lv3'].forEach(id=>{const d=by[id];if(!d)return;const its=d.items.filter(x=>/^[A-Za-z][A-Za-z'\- ]*$/.test(x.w)&&x.m);
  its.forEach((it,i)=>{const c=others(its,i,x=>x.m,3,x=>(x.pos===it.pos||!it.pos)&&!near(x.m,it.m));if(c.length<3)return;
    lw.push({k:'lw:'+it.k,cat:d.title.replace(/\s.*$/,''),say:it.w,c:[it.m].concat(c),e:`${it.w}（${it.pos||''}）${it.m}`})})});
// 2) 会話フレーズの聞き取り・3) 応答を選ぶ
const kw=D.decks.filter(d=>/^kw\d+$/.test(d.id));const ph=[],rs=[];
kw.forEach(d=>d.items.forEach(it=>{const w=strip(it.w);if(w&&it.m)ph.push({it,w,d:d.id})}));
ph.forEach((x,i)=>{const c=others(ph,i,y=>y.it.m,3,y=>!near(y.it.m,x.it.m));if(c.length<3)return;
  D.__lp=D.__lp||[];D.__lp.push({k:'lp:'+x.it.k,cat:by[x.d]?by[x.d].title.replace(/^日常英会話\s*/,''):'',say:x.w,c:[x.it.m].concat(c),e:`${x.w}　${x.it.m}`})});
const dl=[];
kw.forEach(d=>d.items.forEach(it=>{const m=String(it.ex||'').match(/^A:\s*(.+?)\s+B:\s*(.+)$/);if(!m)return;const a=strip(m[1]),b=strip(m[2]);if(!/[?.!]$/.test(a))return;dl.push({it,a,b,d:d.id})}));
dl.forEach((x,i)=>{if(rs.some(r=>r.say===x.a))return;const c=others(dl,i,y=>y.b,3,y=>y.d!==x.d&&!GEN.has(y.b)&&y.b!==x.b);if(c.length<3)return;
  rs.push({k:'lq:'+x.it.k,cat:'応答',say:x.a,c:[x.b].concat(c),e:`A: ${x.a}　B: ${x.b}（${strip(x.it.w)}＝${x.it.m}）`,en:true})});
// 4) 書き取り（英作文の例文・会話の例）
const dict=[];
if(by.wrei)by.wrei.items.forEach(it=>{if(it.w.split(' ').length>=4)dict.push({k:'ld:'+it.k,cat:'英作文の例文',en:it.w,ja:it.m})});
dl.forEach(x=>{if(x.a.split(' ').length>=4)dict.push({k:'ld:a:'+x.it.k,cat:'会話',en:x.a,ja:''})});
D.decks.push({id:'lw',type:'mc',title:'単語の聞き取り',sub:'音声を聞いて意味を選ぶ（Lv1〜Lv3）',items:lw,listen:true});
D.decks.push({id:'lp',type:'mc',title:'会話フレーズの聞き取り',sub:'音声を聞いて意味を選ぶ',items:D.__lp||[],listen:true});
D.decks.push({id:'lq',type:'mc',title:'応答を選ぶ',sub:'話しかけを聞いて、自然な返事を選ぶ',items:rs,listen:true});
D.decks.push({id:'ld',type:'dict',title:'書き取り（ディクテーション）',sub:'聞いた英文をそのまま書く',items:dict,listen:true});
// 5) 話す練習（音読・シャドーイング）
const sp=[];
if(by.wrei)by.wrei.items.forEach(it=>sp.push({k:'sp:'+it.k,cat:'英作文の例文',en:it.w,ja:it.m}));
kw.forEach(d=>d.items.forEach(it=>{const w=strip(it.w);if(!w||/…/.test(w)||w.split(' ').length<2)return;sp.push({k:'sp:'+it.k,cat:by[d.id]?by[d.id].title:'',en:w,ja:it.m})}));
D.decks.push({id:'spk',type:'speak',title:'話す練習（音読・シャドーイング）',sub:'英文を声に出し、音声認識で確かめる',items:sp,listen:true});
delete D.__lp;
})();

;
/* data-extra.js */
// 要約（英検形式）とAI会話の場面 ― 本文は既存の長文、場面はこのアプリ用に作成
(function(){
const D=window.EIGO_DATA,by={};D.decks.forEach(d=>by[d.id]=d);
const items=[];['jr','tr'].forEach(id=>{const d=by[id];if(!d)return;d.items.forEach((p,i)=>items.push({k:'sm:'+id+':'+i,title:p.title,topic:p.topic,paras:p.paras,src:id==='jr'?'入試':'TOEFL'}))});
D.decks.push({id:'summ',type:'summ',title:'要約（英検準1級形式）',sub:'長文を読み、45〜55語の英語で要約してAIが採点',items});
window.EIGO_RP=[
 {id:'conf',t:'学会発表の質疑応答',me:'あなたは発表者',ai:'a curious audience member at an international medical conference who just heard the user present a study on sleep and mood in adolescents. Ask one probing question at a time about methods, sample, limitations or clinical implications.',first:true,lv:'formal'},
 {id:'chair',t:'学会で座長に質問する',me:'あなたは聴衆',ai:'a presenter at an academic conference who just finished a talk on a new screening tool for depression. Answer the user\'s questions politely and sometimes ask them to clarify.',first:false,lv:'formal'},
 {id:'meet',t:'会議で意見を述べる',me:'あなたは会議の参加者',ai:'a team leader running a meeting about whether to postpone a product launch by two months. Ask for the user\'s opinion, push back politely, and try to reach a decision.',first:true,lv:'formal'},
 {id:'net',t:'交流会で研究を紹介する',me:'あなたは研究者',ai:'a friendly researcher from another country chatting at a conference reception. Make small talk, ask about the user\'s work and suggest keeping in touch.',first:true,lv:'formal'},
 {id:'phone',t:'電話で予約を変更する',me:'あなたは予約した客',ai:'a receptionist at a dental clinic answering the phone. The user wants to change their appointment. Ask for name, current date and preferred new time.',first:true,lv:'business'},
 {id:'interview',t:'英語の面接',me:'あなたは応募者',ai:'an interviewer for a research position at a university hospital. Ask one interview question at a time and follow up on the answers.',first:true,lv:'formal'},
 {id:'doctor',t:'病院で症状を伝える',me:'あなたは患者',ai:'a doctor at a clinic abroad. Ask the user about their symptoms step by step (when it started, where it hurts, other symptoms).',first:true,lv:'daily'},
 {id:'hotel',t:'ホテルのチェックイン',me:'あなたは宿泊客',ai:'a hotel front desk clerk. Check the user in, confirm the reservation, explain breakfast and Wi-Fi, and respond to requests.',first:true,lv:'daily'},
 {id:'rest',t:'レストランで注文する',me:'あなたは客',ai:'a waiter at a casual restaurant. Greet the user, take their order, ask about preferences and offer dessert.',first:true,lv:'daily'},
 {id:'way',t:'道を聞かれて教える',me:'あなたは地元の人',ai:'a tourist in Tokyo who is lost and wants to get to Tokyo Station. Ask the user for directions and ask follow-up questions.',first:true,lv:'daily'},
 {id:'chat',t:'友だちと週末の話',me:'あなたは友だち',ai:'a friendly coworker chatting on Monday morning about the weekend and plans for next weekend.',first:true,lv:'daily'},
 {id:'shop',t:'買い物で返品する',me:'あなたは客',ai:'a store clerk. The user wants to return a sweater. Ask why, ask for the receipt, and offer an exchange or refund.',first:false,lv:'daily'}
];
window.EIGO_RP.forEach(x=>x.k='rp:'+x.id);
D.decks.push({id:'rp',type:'rp',title:'AIと会話（ロールプレイ）',sub:'AIが相手役。学会・会議・旅行などの場面で話す',items:window.EIGO_RP});
})();

